   "title": "ວິທີແຍກ ຫຼື ລວມຄຳບັນຍາຍສອງພາສາ – AI-SRTSub",
   "desc": "ສີ່ວິທີໃນການຕັດຄຳບັນຍາຍສອງພາສາ: ຮັກສາໄວ້ພຽງຕິດຕາມດຽວ, ແຍກອອກເປັນສອງໄຟລ໌, ຫຼື ລວມເຂົ້າເປັນລາຍການສອງແຖວ. ตรวจຈັບທັງສອງຮູບແບບອັດຕະໂນມັດ ຢູ່ໃນບຣາວເຊີຂອງທ່ານ.",
   "h1": "ວິທີການຕັດຄຳບັນຍາຍສອງພາສາ",
   "intro": "ຕ້ອງການແຍກຄຳບັນຍາຍສອງພາສາ, ລວມພວກມັນເຂົ້າກັນ, ຫຼື ຮັກສາໄວ້ພຽງຕິດຕາມດຽວບໍ? ຄຳແນະນຳນີ້ຈະພາໄປເບິ່ງທັງສີ່ໂໝດ: ວິທີການກວດຈັບເຮັດວຽກແນວໃດ, ຄວນເລືອກໂໝດໃດ, ແລະ ທ່ານຈະໄດ້ຫຍັງແດ່ໃນການສົ່ງອອກ.",
   "ctaText": "ເປີດເຄື່ອງມືຕັດຄຳບັນຍາຍສອງພາສາ"
