     "ການແປງລະຫວ່າງຕົວອັກສອນແບບຫຍໍ້ ແລະ ດັ້ງເດີມບໍ່ແມ່ນພຽງແຕ່ການຂຽນແຕ່ລະຕົວອັກສອນໃຫ້ຕ່າງອອກໄປ. ຄຳສັບແບບຫຍໍ້ຄຳດຽວກັນອາດຈະກົງກັບຄຳສັບທີ່ແຕກຕ່າງກັນໃນແຕ່ລະພາກພື້ນ — ຄຳວ່າ \"ຊອບແວ\" ລະຫວ່າງໄຕ້ຫວັນກັບຜືນແຜ່ນດິນໃຫຍ່ແມ່ນບໍ່ຄືກັນ, ແລະ ຮົງກົງກໍຍັງມີຮູບແບບອື່ນອີກ. ເຄື່ອງມືແປງນີ້ຈະແຍກສິ່ງເຫຼົ່ານີ້ອອກຈາກກັນ:"
