     "**ເພື່ອເອົາເນື້ອເພງໃສ່ວີດີໂອ ຫຼື ປະມວນຜົນຕໍ່ໄປ, ໃຫ້ສົ່ງອອກເປັນ SRT.** ຕິດຕາມຄຳບັນຍາຍວີດີໂອ, ເຄື່ອງມືຄຳບັນຍາຍ ແລະ ຊອບແວຕັດຕໍ່ອ່ານ SRT ໄດ້. ໃນການສົ່ງອອກ ແຕ່ລະບັນທັດຈະສະແດງຈົນກວ່າບັນທັດຕໍ່ໄປຈະເລີ່ມຕົ້ນ, ແລະ ບັນທັດສຸດທ້າຍຈະກັບຄືນໄປຫາ 2 ວິນາທີ.",
