     "**ຈະເປັນແນວໃດຖ້າເຄື່ອງຫຼິ້ນບໍ່ສົນໃຈຮູບແບບໃນ ASS ທີ່ສົ່ງອອກ?** ຮູບແບບຕ່າງໆຖືກເກັບໄວ້ພາຍໃນໄຟລ໌, ແຕ່ການຮອງຮັບ ASS ຂອງເຄື່ອງຫຼິ້ນແຕກຕ່າງກັນໄປ. ຖ້າທ່ານຕ້ອງການລັກສະນະທີ່ພົກພາໄດ້ງ່າຍກວ່າ, ให้ສົ່ງອອກຮູບແບບ VTT ສອງພາສາ.",
     "**ຂ້ອຍຈະກັບຄືນໄປຫາແມ່ແບບເລີ່ມຕົ້ນຫຼັງຈາກເຮັດມັນພັງໄດ້ແນວໃດ?** \"ກູ້ຄືນພາຣາສະເຕີເລີ່ມຕົ້ນ\" ໃນບລັອກ ASS ແລະ \"ກູ້ຄືນຄ່າເລີ່ມຕົ້ນຂອງແມ່ແບບ\" ໃນບລັອກ VTT ຈະຣີເຊັດພາກສ່ວນຂອງຕนເອງ.",
