   "title": "ບໍ່ແມ່ນການແລກປ່ຽນຕົວອັກສອນ – ການແປງແບບໜຶ່ງຕໍ່ຫຼາຍ ແລະ ຄຳສັບຕາມພາກພື້ນ – AI-SRTSub",
