     "ກຸ່ມລຸ່ມສຸດຂອງ 9 ທິດທາງແມ່ນກຸ່ມທີ່ແປງກັບຄືນ: ດັ້ງເດີມ → ແບບຫຍໍ້, ໄຕ້ຫວັນ → ແບບຫຍໍ້, ຮ່ອງກົງ → ແບບຫຍໍ້."
