   "desc": "ຕັດໄຟລ໌ດຽວອອກເປັນສ່ວນຍ່ອຍຕາມໄລຍະເວລາ ຫຼື ຈຳນວນທ່ອນ, ຣີເຊັດແຕ່ລະສ່ວນໃຫ້ເລີ່ມທີ່ສູນ, ຫຼື ເຊື່ອມຕໍ່ຫຼາຍໄຟລ໌ເຂົ້າກັນຕາມລຳດັບ ຫຼື ຈັດຮຽງຕາມເສັ້ນເວລາ. ໝາຍເລກທ່ອນຖືກຈັດລຳດັບໃຫມ່, ຂໍ້ຄວາມບໍ່ຖືກແຕະຕ້ອງ.",
   "h1": "ວິທີແບ່ງ ແລະ ລວມຊັບໄຕເຕີ",
   "intro": "ຕັດໄຟລ໌ຊັບໄຕເຕີຍາວໆໜຶ່ງໄຟລ໌ອອກເປັນສ່ວນຍ່ອຍ, ຫຼື ລວມໄຟລ໌ທີ່ກະແຈກກະຈາຍຫຼາຍໄຟລ໌ເຂົ້າເປັນໄຟລ໌ດຽວ. ການຕັດຈະຕົກຢູ່ທີ່ຂອບຂອງລາຍການສະເໝີ — ປະໂຫຍກຈະບໍ່ຖືກຕັດຂາດເຄິ່ງ.",
   "ctaText": "ເປີດເຄື່ອງມືແບ່ງ ແລະ ລວມ"
