   "desc": "ຕາຕະລາງຄຳສັບແກ້ໄຂຄຳສັບດຽວກັນທີ່ຖືກແປບໍ່ສອດຄ່ອງກັນ: ເວລາໃດຄວນສ້າງ, ວິທີການນຳໃຊ້ຄືນທົ່ວທັງລະດູການ, ເປັນຫຍັງການຈັບຄູ່ຄຳສັບທັງໝົດຈຶ່ງໃຊ້ບໍ່ໄດ້ໃນພາສາຈີນ, ແລະສິ່ງໃດທີ່ບໍ່ຄວນມອບໃຫ້ມັນ.",
   "h1": "ຕາຕະລາງຄຳສັບ: ການຮັກສາຄວາມສອດຄ່ອງຕະຫຼອດລະດູການ",
   "intro": "ເມື່ອກະລຸນາຊື່ A ໃນຕອນທີໜຶ່ງ ແລະ B ໃນຕອນທີເຈັດ, ຜູ້ຊົມຈະຄິດວ່າພວກເຂົາເປັນຕົວລະຄອນສອງຕົວ. ຕາຕະລາງຄຳສັບປ้องกันສິ່ງນั้นຢ່າງແນ່ນອນ — ມັນແກ້ໄຂວ່າสิ่งຕ່າງໆຖືກຮຽກວ່າຫຍັງ.",
