     "**ໄວຍະກອນ ແລະ ໂຄງສ້າງປະໂຫຍກ** — ທ່ານບໍ່ສາມາດປ່ຽນຄຳສັບໃຫ້ເປັນປະໂຫຍກໄດ້; ວຽກລະດັບປະໂຫຍກກັບຄືນໄປຫາ [[ການແປຄຳບັນຍາຍເຊີງເລິກ|/translate.html]] ຫຼື ມະນຸດ.",
     "**ການລ້າງເນື້ອຫາ** — ການລຶບທັງບັນທັດເຊັ່ນ: ລາຍນ້ຳ, ໂຄສະນາ ແລະ ຄິວ SDH ເປັນຂອງ [[ການລ້າງຄຳບັນຍາຍ|/clean.html]]; ກົດລະບຽບຕາຕະລາງຄຳສັບທົດແທນ, ພວກມັນບໍ່ໄດ້ລຶບບັນທັດ.",
