    "h2": "ເຄື່ອງມື ແລະ ຄູ່ມືທີ່ກ່ຽວຂ້ອງ",
    "ps": [
     "ສຳລັບຄູ່ມືແບບເຕັມຮູບແບບໃຫ້ເບິ່ງ [[ວິທີການປ່ຽນແທນຄຳສັບແບບຊຸດໃນຄຳບັນຍາຍ|/guides/glossary.html]]; ຖ້າເນື້ອຫາມີສິ່ງເປື້ອນເປິໃຫ້ຣັນ [[ການລ້າງຄຳບັນຍາຍ|/clean.html]] ກ່ອນ; ເມື່ອຊື່ຖືກຕົກລົງແລ້ວ ແລະ ທ່ານຕ້ອງການພາສາອື່ນໃຫ້ໄປທີ່ [[ການແປຄຳບັນຍາຍ|/translate.html]]; ແລະ ຣັນຜົນໄດ້ຮັບຜ່ານ [[การກວດສອບຄຸນະພາບຄຳບັນຍາຍ|/qc.html]]."
    ]
