   "intro": "ຄຳບັນຍາຍທີ່ເຮັດສຳເລັດແລ້ວບໍ່ພ້ອມທີ່ຈະສົ່ງມອບ: ບັນຫາທີ່ຜູ້ຊົມສັງເກດເຫັນຕັ້ງແຕ່ແວບທຳອິດແມ່ນບັນຫາທີ່ທ່ານບໍ່ສາມາດເຫັນໄດ້ຫຼັງຈາກເບິ່ງມາເປັນຮ້ອຍຄັ້ງ. ລາຍການກວດສອບນີ້ກວມເອົາຮອບສຸດທ້າຍນັ້ນ.",
